package main
import("os";"syscall";"encoding/binary";"encoding/hex";"encoding/json";"crypto/sha256";"strconv";"fmt";"path/filepath";"strings")
const magic uint64=0x314246383831474f
var le=binary.LittleEndian
func header(b []byte)(map[string]any,error){
 if len(b)!=136&&len(b)!=11088712{return nil,fmt.Errorf("capture bytes")};if le.Uint32(b)!=80||le.Uint32(b[4:])!=1||le.Uint64(b[8:])!=magic{return nil,fmt.Errorf("header ABI")};r:=map[string]any{"nonce":fmt.Sprintf("%016x",le.Uint64(b[80:])),"begin":le.Uint64(b[88:]),"end":le.Uint64(b[96:])};for i,n:=range []string{"code","read_words","written_words","verified_zero","blank_attempted","blank_verified","reserved0","reserved1"}{r[n]=le.Uint32(b[104+4*i:])};if le.Uint32(b[128:])!=0||le.Uint32(b[132:])!=0||le.Uint32(b[108:])>2772144||le.Uint32(b[112:])>2772144||le.Uint32(b[116:])>2772144{return nil,fmt.Errorf("capture fields")};return r,nil
}
func main(){r:=map[string]any{"ok":false,"hardware_command_submitted":false};defer func(){if e:=recover();e!=nil{r["error"]=fmt.Sprint(e)};json.NewEncoder(os.Stdout).Encode(r);if r["ok"]!=true{os.Exit(1)}}();must:=func(e error){if e!=nil{panic(e)}};must(fullOSGuard());if len(os.Args)<2{panic("status | read/result/blank nonce16 exclusive-path")};mode:=os.Args[1];nonce:=uint64(0);path:="";if mode=="status"{if len(os.Args)!=2{panic("status arguments")}}else{if (mode!="read"&&mode!="result"&&mode!="blank")||len(os.Args)!=4{panic("mode/arguments")};var e error;nonce,e=strconv.ParseUint(os.Args[2],16,64);must(e);if len(os.Args[2])!=16||nonce==0||strings.ToLower(os.Args[2])!=os.Args[2]{panic("nonce")};path=os.Args[3];if !strings.EqualFold(filepath.Dir(path),`C:\OpenG81\payloads`)||filepath.Base(path)!="G188-"+mode+"-"+os.Args[2]+".bin"{panic("exclusive project path")}}
 ptr,_:=syscall.UTF16PtrFromString(`\\.\OpenG188`);h,e:=syscall.CreateFile(ptr,syscall.GENERIC_READ|syscall.GENERIC_WRITE,0,nil,3,0,0);must(e);defer syscall.CloseHandle(h)
 q:=make([]byte,32);le.PutUint32(q,32);le.PutUint32(q[4:],1);le.PutUint64(q[8:],magic);le.PutUint64(q[16:],nonce);n,code:=80,uint32(0x226cc0);if mode=="read"{n=11088712;code=0x22ecc4};if mode=="result"{n=11088712;code=0x226ccc};if mode=="blank"{n=136;code=0x22ecc8};b:=make([]byte,n)
 var f *os.File;if path!=""{f,e=os.OpenFile(path,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);must(e);defer f.Close()};var got uint32;r["hardware_command_submitted"]=mode=="read"||mode=="blank";must(syscall.DeviceIoControl(h,code,&q[0],32,&b[0],uint32(n),&got,nil));if got!=uint32(n){panic("reply size")}
 if mode=="status"{if le.Uint32(b)!=80||le.Uint64(b[8:])!=magic{panic("status identity")};r["attempts"]=le.Uint32(b[44:]);r["map_calls"]=le.Uint32(b[40:]);r["ready"]=le.Uint32(b[48:]);r["fault"]=le.Uint32(b[52:])}else{written,e:=f.Write(b);must(e);if written!=len(b){panic("short file write")};must(f.Sync());must(f.Close());sum:=sha256.Sum256(b);r["path"]=path;r["sha256"]=hex.EncodeToString(sum[:]);r["bytes"]=len(b);v,e:=header(b);must(e);if le.Uint64(b[80:])!=nonce{panic("reply nonce")};r["result"]=v};r["ok"]=true
}
